import axios, {
  type AxiosError,
  type AxiosRequestConfig,
  type InternalAxiosRequestConfig,
} from 'axios'
import {
  AUTH_STORAGE_KEY,
  type AuthSession,
} from '@/types/auth/auth'

let onUnauthorized: (() => void) | null = null
let sessionRefreshHandler: (() => Promise<boolean>) | null = null
let refreshInFlight: Promise<boolean> | null = null

/** Refresh Sanctum tokens when fewer than this many ms remain. */
const REFRESH_WITHIN_MS = 10 * 60 * 1000

/** Shared Spotify/API cooldown after a 429 (ms since epoch). */
let rateLimitUntilMs = 0

export function setUnauthorizedHandler(handler: (() => void) | null): void {
  onUnauthorized = handler
}

export function setSessionRefreshHandler(
  handler: (() => Promise<boolean>) | null,
): void {
  sessionRefreshHandler = handler
}

function shouldRefreshSession(session: AuthSession | null): boolean {
  if (!session?.expiresAt) return false
  const expiresAtMs = Date.parse(session.expiresAt)
  if (!Number.isFinite(expiresAtMs)) return false
  const msLeft = expiresAtMs - Date.now()
  return msLeft > 0 && msLeft <= REFRESH_WITHIN_MS
}

function isAuthBootstrapUrl(url: string): boolean {
  return url.includes('/auth/login') || url.includes('/auth/refresh')
}

async function maybeRefreshSession(url: string): Promise<void> {
  if (isAuthBootstrapUrl(url) || !sessionRefreshHandler) return
  if (!shouldRefreshSession(readStoredSession())) return

  if (!refreshInFlight) {
    refreshInFlight = sessionRefreshHandler().finally(() => {
      refreshInFlight = null
    })
  }
  await refreshInFlight
}

export function readStoredSession(): AuthSession | null {
  try {
    const raw = localStorage.getItem(AUTH_STORAGE_KEY)
    if (!raw) return null
    const parsed = JSON.parse(raw) as AuthSession
    if (!parsed?.token) return null
    return parsed
  } catch {
    return null
  }
}

export function writeStoredSession(session: AuthSession | null): void {
  if (!session) {
    localStorage.removeItem(AUTH_STORAGE_KEY)
    return
  }
  localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify(session))
}

export function getRateLimitCooldownRemainingMs(): number {
  return Math.max(0, rateLimitUntilMs - Date.now())
}

export function isRateLimited(): boolean {
  return getRateLimitCooldownRemainingMs() > 0
}

function armRateLimitCooldown(retryAfterHeader: string | undefined): void {
  const retryAfterSec = Number.parseInt(retryAfterHeader ?? '', 10)
  const waitMs = Number.isFinite(retryAfterSec) && retryAfterSec > 0
    ? retryAfterSec * 1000
    : 8000
  rateLimitUntilMs = Math.max(rateLimitUntilMs, Date.now() + waitMs)
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => {
    window.setTimeout(resolve, ms)
  })
}

type RetriableConfig = InternalAxiosRequestConfig & {
  __rateLimitRetryCount?: number
}

const http = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL,
  headers: {
    Accept: 'application/json',
    'Content-Type': 'application/json',
  },
})

http.interceptors.request.use(async (config: InternalAxiosRequestConfig) => {
  const remaining = getRateLimitCooldownRemainingMs()
  if (remaining > 0) {
    await sleep(Math.min(remaining, 15000))
  }

  await maybeRefreshSession(config.url ?? '')

  const session = readStoredSession()
  if (session?.token) {
    config.headers.Authorization = `Bearer ${session.token}`
  }

  // Let the browser set multipart boundary.
  if (typeof FormData !== 'undefined' && config.data instanceof FormData) {
    delete config.headers['Content-Type']
  }

  return config
})

http.interceptors.response.use(
  (response) => response,
  async (error: AxiosError) => {
    if (error.response?.status === 401) {
      const url = error.config?.url ?? ''
      const isLoginRequest = url.includes('/auth/login')
      // Integration modules may historically return 401 for provider reauth;
      // never clear the Nexus Sanctum session for those paths.
      const isIntegrationRequest =
        url.includes('/api/v1/github') ||
        url.includes('/api/v1/spotify') ||
        url.includes('/github/') ||
        url.includes('/spotify/')
      if (!isLoginRequest && !isIntegrationRequest) {
        writeStoredSession(null)
        onUnauthorized?.()
      }
      return Promise.reject(error)
    }

    if (error.response?.status === 429 && error.config) {
      const config = error.config as RetriableConfig
      const retries = config.__rateLimitRetryCount ?? 0
      armRateLimitCooldown(error.response.headers?.['retry-after'])

      if (retries < 2) {
        config.__rateLimitRetryCount = retries + 1
        const wait = Math.min(
          getRateLimitCooldownRemainingMs() || 2000 * (retries + 1),
          15000,
        )
        await sleep(wait)
        return http.request(config as AxiosRequestConfig)
      }
    }

    return Promise.reject(error)
  },
)

/**
 * Multipart POST with optional upload progress. Lets axios set Content-Type
 * (including boundary) for FormData.
 */
export async function postMultipart<T>(
  url: string,
  formData: FormData,
  onProgress?: (percent: number) => void,
): Promise<T> {
  const { data } = await http.post<T>(url, formData, {
    onUploadProgress: (event) => {
      if (!onProgress || !event.total) return
      onProgress(Math.round((event.loaded / event.total) * 100))
    },
  })
  return data
}

export default http
